import {Icon, Menu, MenuItem} from '@ui-kitten/components';
import {Action, IACTION, LIST_ACTION} from './helper';
import {KEY_TASK} from '../../../../helper';
import BottomSheetCM from '../../../../../../components/BottomSheet';
import {useState} from 'react';
import TextFieldCM from '../../../../../../components/TextField';
import ButtonCM from '../../../../../../components/Button';
import useBoardStore from '../../../../store';
import {useBoardService} from '../../../../../../../hooks/apiHooks/useAPI';
import Toast from 'react-native-toast-message';
import ModalConfirmCM from '../../../../../../components/ModalConfirm';
import {Color} from '../../../../../../../constants';
import {ITask} from '../../../../store/interface';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import ModalSelectUser from '../../../../../../components/ModalSelectUser';
import AuthorityAndShareScreen from '../../../../../../components/Authority';

type Props = {
  taskSelect?: ITask;
  onClose?: () => void;
  keyTask: KEY_TASK;
};

const ListActionScreen = ({taskSelect, onClose, keyTask}: Props) => {
  const [isVisible, setIsVisable] = useState<Action | null>(null);
  const [valueName, setValueName] = useState(taskSelect?.name);

  const {listHeaderTask, addListHeaderTaskByKey} = useBoardStore();
  const BoardServices = useBoardService();
  const handleAction = (action: IACTION) => {
    switch (action.action) {
      case Action.RENAME:
        setIsVisable(Action.RENAME);
        break;
      case Action.DELETE:
        setIsVisable(Action.DELETE);
        break;
      case Action.COPY:
        handleCopyTask();
        break;
      case Action.ASSIGN:
        setIsVisable(Action.ASSIGN);
        break;
      case Action.SHARE_PERMISSIONS:
        setIsVisable(Action.SHARE_PERMISSIONS);
        break;
      default:
        return;
    }
  };

  const handleAssign = () => {};

  const handleChangeName = async () => {
    try {
      const data = await BoardServices.saveListTask(
        {
          ...taskSelect,
          name: valueName,
        },
        'PUT',
      );
      if (data) {
        const newData = listHeaderTask
          .find(header => header.key === keyTask)
          ?.child?.map(task => ({
            ...task,
            name: task.id === taskSelect?.id ? valueName : task.name,
          })) as ITask[];
        addListHeaderTaskByKey(newData, keyTask);
        onClose?.();
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Đổi tên bị lỗi',
        });
      }
    } catch (error) {}
  };

  const handleDelete = async () => {
    try {
      const data = await BoardServices.deleteTaskById(taskSelect?.id);
      if (data) {
        const newData = listHeaderTask
          .find(header => header.key === keyTask)
          ?.child?.filter(task => task.id !== taskSelect?.id) as ITask[];
        addListHeaderTaskByKey(newData, keyTask);
        onClose?.();
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {}
  };

  const handleCopyTask = async () => {
    try {
      const data = await BoardServices.copyTaskFormOtherTask(taskSelect?.id);
      if (data) {
        const newData = listHeaderTask.find(header => header.key === keyTask)
          ?.child as ITask[];
        addListHeaderTaskByKey([data, ...newData], keyTask);
        onClose?.();
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {}
  };
  return (
    <>
      <Menu>
        {LIST_ACTION.map(action => (
          <MenuItem
            onPress={() => handleAction(action)}
            accessoryLeft={<Icon name={action.icon} />}
            key={action.id}
            title={action.name}
          />
        ))}
      </Menu>

      <BottomSheetCM
        title="Add"
        withKeyboardAvoidingView
        isVisible={isVisible === Action.RENAME}
        onClose={() => setIsVisable(null)}
        renderContent={
          <>
            <TextFieldCM value={valueName} onChangeText={setValueName} />
            <ButtonCM label="Lưu" onPress={handleChangeName} />
          </>
        }
      />

      <ModalConfirmCM
        isVisible={isVisible === Action.DELETE}
        onClose={() => setIsVisable(null)}
        title={'HM.titleCancel'}
        content={'HM.contentCancel'}
        type="cancel"
        labelCancel={'HM.cancel'}
        labelConfirm={'CM.labelCancel'}
        styleBtnRight={{backgroundColor: Color.RedE14337}}
        onConfirm={handleDelete}
      />

      {/* <ModalFullScreen
        isVisible={isVisible === Action.ASSIGN}
        children={
          <ModalSelectUser
            onClose={() => setIsVisable(null)}
            type="L"
            assignGroupList={taskSelect?.assignGroupList}
            assignOrgList={taskSelect?.assignOrgList}
            listTask={taskSelect}
          />
        }
      /> */}

      <ModalFullScreen
        isVisible={isVisible === Action.SHARE_PERMISSIONS}
        children={
          <AuthorityAndShareScreen
            type="L"
            onClose={() => setIsVisable(null)}
            resource={taskSelect}
          />
        }
      />
    </>
  );
};

export default ListActionScreen;
