import {
  Animated,
  findNodeHandle,
  FlatList,
  Keyboard,
  LayoutAnimation,
  Platform,
  Pressable,
  ScrollView,
  TextInput,
  TouchableWithoutFeedback,
  UIManager,
  View,
} from 'react-native';
import TextCM from '../../../../components/Text';
import HeaderScrollView from '../../../../components/Header/HeaderScrollView';
import {CheckBox, Divider, Icon, Input, Spinner} from '@ui-kitten/components';
import {useNavigation, useRoute} from '@react-navigation/native';
import {useEffect, useMemo, useRef, useState} from 'react';
import ItemTask from './component/item';
import {
  useBoardService,
  useTaskService,
} from '../../../../../hooks/apiHooks/useAPI';
import {AssignReviewList, ITaskDetail} from '../task-detail-item/helper';
import {Color, Font, NavigationName} from '../../../../../constants';
import ModalFullScreen from '../../../../components/ModalFullScreen';
import ModalDescription from './component/modal-description';
import Toast from 'react-native-toast-message';
import ModalDate from './component/modal-date';
import {DateUtils} from '../../../../../utils';
import {PRIORITIES} from '../../../board/components/create-new-task/helper';
import useBoardStore from '../../../board/store';
import {ICheckList, ICheckListItem, ITaskActivities} from '../../helper';
import {SafeAreaView} from 'react-native-safe-area-context';
import {IconSend} from '../../../../../assets/images';
import BottomSheetCM from '../../../../components/BottomSheet';
import ModalStatus from './component/modal-status';
import ModalPriority from './component/modal-priority';
import RenderHtml from 'react-native-render-html';
import {useUserStore} from '../../../../../zutand/user-store';
import styles from './styles';
import ModalSelectUser from '../../../../components/ModalSelectUser';
import RenderListUserAssign from '../item-ticket/list-assign';
import ActivitiesScreen from './component/activities';
import {useTranslation} from 'react-i18next';
import AddSubTask from './component/add-sub-task';
import CheckListItem from './component/check-list-item';
import {IUser} from '../../../../../model/interface/account.interface';
import ModalRemind from './component/modal-remind';
import Attractments from './component/attractments';
import TaskReview from './component/task-review';
import TaskRepeat from './component/task-repeat';

if (Platform.OS === 'android') {
  UIManager.setLayoutAnimationEnabledExperimental?.(true);
}

const TaskDetailScreen = () => {
  const {t} = useTranslation();
  const router = useRoute<any>();
  const navigation = useNavigation<any>();
  const taskId = router?.params?.taskId || '';
  const typeDirectFrom = (router?.params?.type as 'task' | 'subTask') || 'task';

  const refScrollView = useRef<ScrollView>(null);
  const [task, setTask] = useState<ITaskDetail>();
  const [isFocusInputComment, setIsFocusInputComment] = useState(false);
  const [taskActivities, setTaskActivities] = useState<ITaskActivities[]>();
  const [subTasks, setSubTasks] = useState<ITaskDetail[]>();
  const [subTasksSelect, setSubTasksSelect] = useState<ITaskDetail>();
  const [checkList, setCheckList] = useState<ICheckList[]>([]);
  const [modalAddDescription, setModalAddDescription] = useState(false);
  const [modalSelectUser, setModalSelectUser] = useState(false);
  const [modalAddSubTask, setModalAddSubTask] = useState(false);
  const [showBottomSheet, setShowBottomSheet] = useState<
    'status' | 'priority' | null | 'statusSubTask'
  >(null);
  const [modalDate, setModalDate] = useState<
    'startDate' | 'dueDate' | 'remind'
  >();
  const [keyboardHeight, setKeyboardHeight] = useState(0);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const animatedPadding = useRef(new Animated.Value(0)).current;

  const TaskService = useTaskService();
  const BoardService = useBoardService();

  const {groupTaskList, listTaskIdSelect} = useBoardStore();
  const {listUser, setListUserInTask} = useUserStore();
  const groupTask = useMemo(
    () => groupTaskList.find(item => item.id === task?.status),
    [groupTaskList, task],
  );

  const attr = useMemo(() => {
    return JSON.parse(groupTask?.attr || '{}');
  }, [groupTask]);

  const priority = useMemo(() => {
    return PRIORITIES.find(item => item.value === task?.priority);
  }, [task]);

  useEffect(() => {
    handleInit();
  }, [taskId]);

  const handleInit = async () => {
    try {
      setIsLoadingData(true);
      await Promise.all([
        getTaskById(),
        getTaskActivitiesById(),
        typeDirectFrom === 'task' && getListTaskSearch(),
        getCheckListById(),
      ]);
    } catch (error) {
    } finally {
      setTimeout(() => {
        setIsLoadingData(false);
      }, 400);
    }
  };

  useEffect(() => {
    const showListener =
      Platform.OS === 'ios' ? 'keyboardWillShow' : 'keyboardDidShow';
    const hideListener =
      Platform.OS === 'ios' ? 'keyboardWillHide' : 'keyboardDidHide';

    const onKeyboardShow = Keyboard.addListener(showListener, e => {
      const height = e.endCoordinates?.height || 0;
      const duration = e.duration || 250;

      if (Platform.OS === 'ios') {
        Animated.timing(animatedPadding, {
          toValue: height,
          duration,
          useNativeDriver: false,
        }).start();
      } else {
        LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
        setKeyboardHeight(height);
      }
    });

    const onKeyboardHide = Keyboard.addListener(hideListener, e => {
      const duration = e?.duration || 250;

      if (Platform.OS === 'ios') {
        Animated.timing(animatedPadding, {
          toValue: 0,
          duration,
          useNativeDriver: false,
        }).start();
      } else {
        LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
        setKeyboardHeight(0);
      }
    });

    return () => {
      onKeyboardShow.remove();
      onKeyboardHide.remove();
    };
  }, []);

  const paddingBottomStyle =
    Platform.OS === 'ios'
      ? {paddingBottom: animatedPadding}
      : {paddingBottom: keyboardHeight};

  const getTaskById = async () => {
    try {
      const data = (await TaskService.getTaskById(taskId)) as ITaskDetail;
      if (data) {
        setTask(data);
        if (typeDirectFrom === 'task') {
          const listUserInTask = data?.assignTaskList?.map(u => {
            const user = listUser?.find(item => item.resourceId === u.userId);
            if (user) return user;
          }) as IUser[];

          setListUserInTask(listUserInTask);
        }
      }
    } catch (error) {}
  };

  const getCheckListById = async () => {
    try {
      const body = {
        taskId: taskId,
      };
      const params = {
        page: 0,
        size: 10000,
        sort: 'createdDate,asc',
      };
      const data = await TaskService.getCheckListTask(body, params);
      if (data) {
        setCheckList(data?.data);
      }
    } catch (error) {}
  };

  const getTaskActivitiesById = async () => {
    try {
      const data = await TaskService.getTaskActivitiesById(taskId);
      if (data) {
        setTaskActivities(data);
      }
    } catch (error) {}
  };

  const getListTaskSearch = async () => {
    try {
      const body = {
        parentId: taskId,
      };
      const params = {
        page: 0,
        size: 10000,
        sort: 'createdDate,asc',
      };
      const data = await BoardService.searchTask(body, params);
      if (data) {
        setSubTasks(data?.data);
      }
    } catch (error) {}
  };

  const handleFocus = (refInputName: any) => {
    setIsFocusInputComment(false);
    const scrollNode = refScrollView.current;
    const scrollHandle = findNodeHandle(scrollNode);
    const node = findNodeHandle(refInputName?.current);
    if (node && scrollHandle) {
      UIManager.measureLayout(
        node,
        scrollHandle,
        () => {},
        (x, y) => {
          refScrollView.current?.scrollTo({
            y: y - 100, // offset tránh đụng bàn phím
            animated: true,
          });
        },
      );
    }
  };

  const handleOnSaveData = async (data: any) => {
    const prevTask = {...task} as ITaskDetail;
    const body = {
      ...task,
      ...data,
    };
    setTask(body);
    try {
      const data = await BoardService.updateTask(body);
      if (data) {
      } else {
        setTask(prevTask);
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {
    } finally {
      setShowBottomSheet(null);
      setModalAddDescription(false);
      setModalDate(undefined);
    }
  };

  const handleOnSaveConfigRemind = async (data: any) => {
    const prevTask = {...task} as ITaskDetail;
    const body = {
      ...task,
      configRemind: data,
    } as ITaskDetail;
    setTask(body);
    try {
      const dataResp = await TaskService.configRemindTask({
        ...data,
        taskId: taskId,
      });
      if (dataResp) {
      } else {
        setTask(prevTask);
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {
    } finally {
      setModalDate(undefined);
    }
  };

  const handleOnSaveSubTask = async (data: any) => {
    const prevSubTask = subTasks && ([...subTasks] as ITaskDetail[]);
    const body = {
      ...subTasksSelect,
      ...data,
    };
    const newSubTask = prevSubTask?.map(subTask =>
      subTask.id === body.id ? body : subTask,
    ) as ITaskDetail[];
    setSubTasks(newSubTask);
    try {
      const data = await BoardService.updateTask(body);
      if (data) {
        const groupTaskStatusCompleted = newSubTask.filter(
          group => group.status === data.status,
        );
        const percent = groupTaskStatusCompleted.length / newSubTask.length;
        setTask({...task, percent: percent} as ITaskDetail);
      } else {
        setSubTasks(prevSubTask);
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {
    } finally {
      setShowBottomSheet(null);
    }
  };

  const handleBack = () => {
    const updatedData = {
      ...task,
    };
    if (typeDirectFrom === 'subTask') {
      navigation.navigate(NavigationName.TaskDetailScreen, {
        taskId: task?.parentId,
        type: 'task',
      });
    } else {
      navigation.navigate(NavigationName.TaskScreen, {
        updatedTask: updatedData,
      });
    }
  };

  const handleAddSubTask = async (data: any) => {
    try {
      const dataUpdate = {
        listTaskId: listTaskIdSelect,
        description: null,
        remindDate: null,
        tags: null,
        taskIn: null,
        assignTaskList: [],
        checkListDtoList: [],
        parentId: taskId,
        status: groupTaskList.find(item => item.type === 'todo')?.id,
        assignGroupList: [],
        assignOrgList: [],
        id: null,
        isAdding: true,
        startDate: data?.startDate || null,
        dueDate: data?.dueDate || null,
        ...data,
      };
      const dataResp = await BoardService.createTask(dataUpdate);
      if (dataResp) {
        setSubTasks([dataResp, ...(subTasks || [])]);
        Toast.show({
          type: 'success',
          text1: 'Thông báo',
          text2: 'Thêm công việc con thành công',
        });
      } else {
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra khi thêm công việc con',
        });
      }
    } catch (error) {}
  };

  const handleChangeValueName = (value: any, idCheckList?: string) => {
    const prevCheckList = [...checkList];
    let dataSelect;
    let prevName;
    const newCheckList = checkList?.map(item => {
      if (item.id === idCheckList) {
        prevName = item.name;
        dataSelect = {...item, name: value};
        return {...item, name: value};
      }
      return item;
    });
    if (prevName === value) {
      return;
    }
    setCheckList(newCheckList);
    try {
      const dataResp = TaskService.updateCheckListTask(dataSelect);
      if (!dataResp) {
        setCheckList(prevCheckList);
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra',
        });
      }
    } catch (error) {}
  };

  const handleChangeValueCheckList = async (
    value: any,
    idCheckList?: string,
    type?: string,
    index?: number,
  ) => {
    let dataSelect;
    let prevName;
    const prevCheckList = [...checkList];
    const newCheckList = checkList?.map(item => {
      if (item.id === idCheckList) {
        const listValue = JSON.parse(item?.value || '[]');
        if (listValue.length) {
          if (type === 'name') {
            prevName = listValue[index as any].name;
          }
          listValue[index as any] = {
            ...listValue[index as any],
            [`${type}`]: value,
          };
        }
        dataSelect = {
          ...item,
          value: JSON.stringify(listValue),
        };
        return {
          ...item,
          value: JSON.stringify(listValue),
        };
      }
      return item;
    });
    if (type === 'name' && prevName === value) {
      return;
    }
    setCheckList(newCheckList);
    try {
      const dataResp = await TaskService.updateCheckListTask(dataSelect);
      if (!dataResp) {
        setCheckList(prevCheckList);
        Toast.show({
          type: 'error',
          text1: 'Thông báo',
          text2: 'Có lỗi xảy ra khi cập nhật danh sách con',
        });
      }
    } catch (error) {}
  };

  const handleAddCheckList = async () => {
    const dataCheckList = {
      name: `Việc cần làm ${checkList?.length + 1}`,
      taskId: taskId,
      template: false,
    };
    try {
      const dataResp = await TaskService.addCheckListTask(dataCheckList);
      if (dataResp) {
        setCheckList([dataResp, ...(checkList || [])]);
      }
    } catch (error) {}
  };

  const handleUpdateCheckList = async (name: string, checkListId?: string) => {
    try {
      if (!name) return;
      const data = {
        name,
        status: false,
        assign: null,
        id: new Date().getTime().toString(),
      };
      const checkListInList = checkList?.find(item => item.id === checkListId);
      if (checkListInList) {
        const value = JSON.parse(checkListInList?.value || '[]');
        const newValue = [...value, data];
        const newCheckList = {
          ...checkListInList,
          value: JSON.stringify(newValue),
        };
        const newCheckListFilter = checkList?.map(item =>
          item.id === checkListId ? newCheckList : item,
        );
        setCheckList(newCheckListFilter);
        const dataResp = await TaskService.updateCheckListTask(newCheckList);
        if (dataResp) {
        } else {
          const reverseCheckListFilter = checkList?.map(item =>
            item.id === checkListId ? checkListInList : item,
          );
          setCheckList(reverseCheckListFilter);
          Toast.show({
            type: 'error',
            text1: 'Thông báo',
            text2: 'Có lỗi xảy ra',
          });
        }
      }
    } catch (error) {}
  };

  const handleClearCheckListValue = async (
    checkListId?: string,
    index?: number,
  ) => {
    try {
      const checkListInList = checkList?.find(item => item.id === checkListId);
      if (checkListInList) {
        const value = JSON.parse(checkListInList?.value || '[]');
        const valueFilter = value?.filter(
          (v: any, idx: number) => idx !== index,
        );
        const newCheckList = {
          ...checkListInList,
          value: JSON.stringify(valueFilter),
        };
        const newCheckListFilter = checkList?.map(item =>
          item.id === checkListId ? newCheckList : item,
        );
        setCheckList(newCheckListFilter);
        const dataResp = await TaskService.updateCheckListTask(newCheckList);
        if (!dataResp) {
          const reverseCheckListFilter = checkList?.map(item =>
            item.id === checkListId ? checkListInList : item,
          );
          setCheckList(reverseCheckListFilter);
          Toast.show({
            type: 'error',
            text1: 'Thông báo',
            text2: 'Có lỗi xảy ra',
          });
        }
      }
    } catch (error) {}
  };

  const handleUpdateTaskReview = (data: AssignReviewList[]) => {
    setTask({
      ...task,
      assignReviewList: data,
    } as ITaskDetail);
  };

  if (isLoadingData) {
    return (
      <SafeAreaView
        style={{
          backgroundColor: '#fff',
          alignItems: 'center',
          justifyContent: 'center',
          flex: 1,
        }}>
        <Spinner />
      </SafeAreaView>
    );
  }

  return (
    <>
      <HeaderScrollView
        ref={refScrollView}
        title={task?.name as any}
        handleBackPress={handleBack}
        renderContent={
          <TouchableWithoutFeedback onPress={() => Keyboard.dismiss()}>
            <View>
              {/* task name */}
              <View style={{paddingHorizontal: 16}}>
                {task && (
                  <ItemTask
                    value={task?.name}
                    onSave={handleOnSaveData}
                    handleFocus={handleFocus}
                  />
                )}
              </View>
              <Divider style={styles.divider} />
              {/* task info */}
              <View style={styles.ctnTaskInfo}>
                <View style={styles.ctnItem}>
                  <TextCM style={styles.ctnTextItem}>Trạng thái</TextCM>
                  <View style={styles.ctnStatus}>
                    <View
                      style={{
                        backgroundColor: `${attr.color}1A`,
                        ...styles.styleStatus,
                      }}>
                      <TextCM
                        style={{
                          color: attr.color,
                        }}>
                        {groupTask?.type === 'custom'
                          ? groupTask?.name
                          : t('board.status-' + groupTask?.type)}
                      </TextCM>
                    </View>
                    <View style={styles.diviverHeight} />
                    <Pressable
                      onPress={() => setShowBottomSheet('status')}
                      style={{
                        ...styles.styleStatusSelect,
                        backgroundColor: `${attr.color}1A`,
                      }}>
                      <Icon
                        fill={attr.color}
                        name="arrow-ios-forward"
                        width={16}
                        height={16}
                      />
                    </Pressable>
                    <View style={{flex: 1}} />
                  </View>
                </View>
                <View style={styles.ctnItem}>
                  <TextCM style={styles.ctnTextItem}>Độ ưu tiên</TextCM>
                  <View style={styles.ctnStatus}>
                    <Pressable onPress={() => setShowBottomSheet('priority')}>
                      {!priority ? (
                        <TextCM
                          style={{
                            color: '#00204D47',
                          }}>
                          {'Chọn độ ưu tiên'}
                        </TextCM>
                      ) : (
                        <View
                          style={{
                            ...styles.viewPriority,
                            borderColor: `${priority.color}`,
                          }}>
                          {priority?.icon}
                        </View>
                      )}
                    </Pressable>
                    <View style={{flex: 1}} />
                  </View>
                </View>
              </View>
              <Divider style={styles.divider} />

              {/* task repeat */}
              <View
                style={{
                  ...styles.ctnTaskDate,
                  alignItems: 'center',
                }}>
                {/* <Icon name="repeat-outline" width={20} height={20} /> */}
                <View style={{flex: 1}}>
                  <TaskRepeat taskId={taskId} startDate={task?.startDate} />
                </View>
              </View>
              <Divider style={styles.divider} />

              {/* task description */}
              <View style={styles.ctnDescription}>
                <Pressable
                  onPress={() => setModalAddDescription(true)}
                  style={styles.ctnOpenDescription}>
                  <Icon name="menu" width={24} height={24} />
                  {task?.description ? (
                    <RenderHtml
                      containerStyle={{flex: 1}}
                      source={{
                        html: task?.description,
                      }}
                    />
                  ) : (
                    <TextCM>{'Add a description'}</TextCM>
                  )}
                </Pressable>
              </View>

              <Divider style={styles.divider} />
              {/* task date */}
              <View style={styles.ctnTaskDate}>
                <Icon name="clock" width={20} height={20} />
                <View style={styles.viewDate}>
                  <Pressable onPress={() => setModalDate('startDate')}>
                    <TextCM style={{fontFamily: Font.InterMedium500}}>
                      {DateUtils.convertDateToDDMMYYYY_H_M(
                        task?.startDate as any,
                      ) || 'Start Date'}
                    </TextCM>
                  </Pressable>
                  <Divider style={{height: 2}} />
                  <Pressable onPress={() => setModalDate('dueDate')}>
                    <TextCM style={{fontFamily: Font.InterMedium500}}>
                      {DateUtils.convertDateToDDMMYYYY_H_M(
                        task?.dueDate as any,
                      ) || 'Due Date'}
                    </TextCM>
                  </Pressable>
                  <Divider style={{height: 2}} />
                  <Pressable onPress={() => setModalDate('remind')}>
                    <TextCM style={{fontFamily: Font.InterMedium500}}>
                      {DateUtils.convertDateToDDMMYYYY_H_M(
                        task?.configRemind?.dateStart as any,
                      ) || 'Remind Date'}
                    </TextCM>
                  </Pressable>
                </View>
              </View>

              <Divider style={styles.divider} />
              {/* task label */}
              <View
                style={{
                  ...styles.ctnTaskDate,
                  alignItems: 'center',
                }}>
                <Icon name="pricetags" width={20} height={20} />
                <View style={{flex: 1}}>
                  {!task?.tags ? (
                    <TextCM>Label</TextCM>
                  ) : (
                    <View style={styles.ctnTags}>
                      {task?.tags?.map((tag: string, index: number) => (
                        <View
                          key={index}
                          style={{
                            ...styles.tagsItem,
                            borderColor: Color.borderColor,
                          }}>
                          <TextCM numberOfLines={1} style={styles.txtTag}>
                            {tag}
                          </TextCM>
                        </View>
                      ))}
                    </View>
                  )}
                </View>
              </View>
              <Divider style={styles.divider} />

              {/* task user assign */}
              <View
                style={{
                  ...styles.ctnTaskDate,
                  alignItems: 'center',
                }}>
                <Icon name="people" width={20} height={20} />
                <Pressable
                  onPress={() => setModalSelectUser(true)}
                  style={{flex: 1}}>
                  {task?.assignTaskList.length == 0 ? (
                    <TextCM>Người thực hiện</TextCM>
                  ) : (
                    <RenderListUserAssign
                      assignTaskList={task?.assignTaskList}
                      assignGroupList={task?.assignGroupList}
                      assignOrgList={task?.assignOrgList}
                    />
                  )}
                </Pressable>
              </View>
              <Divider style={styles.divider} />

              <View
                style={{
                  ...styles.ctnTaskDate,
                  alignItems: 'center',
                }}>
                <Icon name="person" width={20} height={20} />
                <View style={{flex: 1}}>
                  <TaskReview
                    taskId={taskId}
                    assignReviewList={task?.assignReviewList}
                    handleUpdateTask={handleUpdateTaskReview}
                  />
                </View>
              </View>
              <Divider style={styles.divider} />

              {typeDirectFrom === 'task' && (
                <>
                  <View>
                    <View
                      style={{
                        ...styles.ctnTaskDate,
                        alignItems: 'center',
                      }}>
                      <Icon name="file-text-outline" width={20} height={20} />
                      <View style={styles.ctnSubTask}>
                        <TextCM style={styles.ctnTextItem}>Sub tasks</TextCM>
                        <Pressable onPress={() => setModalAddSubTask(true)}>
                          <Icon name="plus" width={20} height={20} />
                        </Pressable>
                      </View>
                    </View>

                    <FlatList
                      data={subTasks}
                      scrollEnabled={false}
                      renderItem={({item}) => {
                        const groupSubTask = groupTaskList.find(
                          task => task.id === item.status,
                        );
                        const attrOfSubTask = JSON.parse(
                          groupSubTask?.attr || '{}',
                        );
                        return (
                          <View
                            style={[
                              styles.ctnViewSubtask,
                              {
                                marginRight: 10,
                              },
                            ]}>
                            <Pressable
                              style={{
                                flex: 2,
                              }}
                              onPress={() => {
                                navigation.navigate(
                                  NavigationName.TaskDetailScreen,
                                  {
                                    taskId: item.id,
                                    type: 'subTask',
                                  },
                                );
                              }}>
                              <TextCM
                                style={{
                                  color: Color.Text,
                                  fontSize: 13,
                                  fontFamily: Font.InterRegular400,
                                }}>
                                - {item.name}
                              </TextCM>
                            </Pressable>

                            <View style={styles.ctnStatus}>
                              <View style={{flex: 1}} />
                              <View
                                style={{
                                  backgroundColor: `${attrOfSubTask.color}1A`,
                                  ...styles.styleStatus,
                                }}>
                                <TextCM
                                  style={{
                                    color: attrOfSubTask.color,
                                  }}>
                                  {groupSubTask?.type === 'custom'
                                    ? groupSubTask?.name
                                    : t('board.status-' + groupSubTask?.type)}
                                </TextCM>
                              </View>
                              <View style={styles.diviverHeight} />
                              <Pressable
                                onPress={() => {
                                  setSubTasksSelect(item);
                                  setShowBottomSheet('statusSubTask');
                                }}
                                style={{
                                  ...styles.styleStatusSelect,
                                  backgroundColor: `${attrOfSubTask.color}1A`,
                                }}>
                                <Icon
                                  fill={attrOfSubTask.color}
                                  name="arrow-ios-forward"
                                  width={16}
                                  height={16}
                                />
                              </Pressable>
                            </View>
                          </View>
                        );
                      }}
                    />
                  </View>
                  <Divider style={styles.divider} />
                </>
              )}

              {/* checklist */}

              <View>
                <View
                  style={{
                    ...styles.ctnTaskDate,
                    alignItems: 'center',
                  }}>
                  <Icon name="briefcase-outline" width={20} height={20} />
                  <View style={styles.ctnSubTask}>
                    <TextCM style={styles.ctnTextItem}>
                      Danh sách việc cần làm
                    </TextCM>
                    <Pressable onPress={handleAddCheckList}>
                      <Icon name="plus" width={20} height={20} />
                    </Pressable>
                  </View>
                </View>

                <FlatList
                  contentContainerStyle={{width: '100%'}}
                  data={checkList}
                  scrollEnabled={false}
                  renderItem={({item}) => {
                    const value = JSON.parse(item?.value || '[]');
                    return (
                      <CheckListItem
                        valueCheckList={value}
                        checkList={item}
                        setCheckList={setCheckList}
                        listCheckList={checkList}
                        handleFocus={handleFocus}
                        handleChangeValueName={handleChangeValueName}
                        handleChangeValueCheckList={handleChangeValueCheckList}
                        handleUpdateCheckList={handleUpdateCheckList}
                        handleClearCheckListValue={handleClearCheckListValue}
                        // assignTaskList={task?.assignTaskList}
                      />
                    );
                  }}
                />
              </View>
              <Divider style={styles.divider} />

              {/* attachments */}
              <Attractments taskId={taskId} />
              <Divider style={styles.divider} />

              {/* task activities */}
              <ActivitiesScreen
                taskActivities={taskActivities?.sort((a, b) => {
                  const aDate = new Date(a.createdDate).getTime();
                  const bDate = new Date(b.createdDate).getTime();
                  return aDate - bDate;
                })}
              />
              <Divider style={styles.divider} />
            </View>
          </TouchableWithoutFeedback>
        }
      />

      <Animated.View
        style={[
          {backgroundColor: '#fff'},
          isFocusInputComment && paddingBottomStyle,
        ]}>
        <SafeAreaView edges={['bottom']} style={styles.ctnInput}>
          <View style={styles.bodyInput}>
            <Input
              onFocus={() => setIsFocusInputComment(true)}
              style={{flex: 1}}
              placeholder="Nhập nội dung..."
            />
            <IconSend width={24} height={24} />
          </View>
        </SafeAreaView>
      </Animated.View>

      <ModalFullScreen
        isVisible={modalAddDescription}
        children={
          <ModalDescription
            onClose={() => setModalAddDescription(false)}
            value={task?.description}
            onSave={handleOnSaveData}
          />
        }
      />

      <ModalFullScreen
        isVisible={modalDate === 'startDate'}
        children={
          <ModalDate
            onClose={() => setModalDate(undefined)}
            value={task?.startDate}
            onSave={handleOnSaveData}
            type="startDate"
          />
        }
      />
      <ModalFullScreen
        isVisible={modalDate === 'dueDate'}
        children={
          <ModalDate
            onClose={() => setModalDate(undefined)}
            value={task?.dueDate}
            onSave={handleOnSaveData}
            type="dueDate"
          />
        }
      />

      <ModalFullScreen
        isVisible={modalDate === 'remind'}
        children={
          <ModalRemind
            onClose={() => setModalDate(undefined)}
            valueConfig={task?.configRemind}
            onSave={handleOnSaveConfigRemind}
          />
        }
      />

      <BottomSheetCM
        title="Status"
        isVisible={showBottomSheet === 'status'}
        onClose={() => setShowBottomSheet(null)}
        renderContent={
          <ModalStatus value={task?.status} onSave={handleOnSaveData} />
        }
      />

      <BottomSheetCM
        title="Status"
        isVisible={showBottomSheet === 'statusSubTask'}
        onClose={() => setShowBottomSheet(null)}
        renderContent={
          <ModalStatus
            value={subTasksSelect?.status}
            onSave={handleOnSaveSubTask}
          />
        }
      />

      <BottomSheetCM
        title="Priority"
        isVisible={showBottomSheet === 'priority'}
        onClose={() => setShowBottomSheet(null)}
        renderContent={
          <ModalPriority onSave={handleOnSaveData} value={task?.priority} />
        }
      />
      <ModalFullScreen
        isVisible={modalSelectUser}
        children={
          <ModalSelectUser
            type="T"
            task={task}
            onClose={() => setModalSelectUser(false)}
          />
        }
      />

      <ModalFullScreen
        isVisible={modalAddSubTask}
        children={
          <AddSubTask
            handleSubmitData={handleAddSubTask}
            onClose={() => setModalAddSubTask(false)}
          />
        }
      />
    </>
  );
};

export default TaskDetailScreen;
